    20	    public void notifyGovernanceOnConfirmation(Reservation reservation) {
    21	        String subject = "Reserva confirmada - quarto " + reservation.getRoomNumber();
    22	        String body = String.format(
    23	            "Entrada: %s | Saída: %s | %d hóspede%s",
    24	            reservation.getCheckIn().format(DATE_FORMATTER),
    25	            reservation.getCheckOut().format(DATE_FORMATTER),
    26	            reservation.getGuests(),
    27	            reservation.getGuests() > 1 ? "s" : ""
    28	        );
    29	
    30	        Message message = new Message(
    31	            messageRepository.getNextMessageId(),
    32	            Message.MessageChannel.EMAIL,
    33	            "governanca@pousadamarealta.com.br",
    34	            subject,
    35	            body
    36	        );
    37	        messageRepository.save(message);
    38	    }
    39	
    40	    public void notifyFinanceOnConfirmation(Reservation reservation) {
    41	        String subject = "Pagamento recebido - reserva " + reservation.getId();
    42	        String body = "Valor pago: " + formatCurrency(reservation.getTotal());
    43	
    44	        Message message = new Message(
    45	            messageRepository.getNextMessageId(),
    46	            Message.MessageChannel.EMAIL,
    47	            "financeiro@pousadamarealta.com.br",
    48	            subject,
    49	            body
    50	        );
    51	        messageRepository.save(message);
    52	    }
    53	
    54	    public void notifyGovernanceOnCancellation(Reservation reservation) {
    55	        String subject = "Reserva cancelada - quarto " + reservation.getRoomNumber();
    56	        String body = String.format(
    57	            "Datas liberadas: %s a %s",
    58	            reservation.getCheckIn().format(DATE_FORMATTER),
    59	            reservation.getCheckOut().format(DATE_FORMATTER)
    60	        );
    61	
    62	        Message message = new Message(
    63	            messageRepository.getNextMessageId(),
    64	            Message.MessageChannel.EMAIL,
    65	            "governanca@pousadamarealta.com.br",
