    67	            body
    68	        );
    69	        messageRepository.save(message);
    70	    }
    71	
    72	    public void notifyFinanceOnCancellation(Reservation reservation) {
    73	        if (reservation.getRefund() != null && reservation.getRefund().compareTo(BigDecimal.ZERO) > 0) {
    74	            String subject = "Reembolso - reserva " + reservation.getId();
    75	            String body = "Valor a devolver: " + formatCurrency(reservation.getRefund());
    76	
    77	            Message message = new Message(
