    29	
    30	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    31	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    32	        Room room = roomRepository.findByNumber(roomNumber);
    33	        if (room == null) {
    34	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    35	        }
    36	
    37	        if (guests < 1 || guests > room.getCapacity()) {
    38	            throw new IllegalArgumentException(guests > room.getCapacity() ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
    39	        }
    40	
    41	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    42	            throw new IllegalArgumentException("INVALID_REQUEST");
    43	        }
    44	
    45	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    46	            if (!reservationRepository.findByRoomAndDate(roomNumber, date).iterator().hasNext()) {
    47	                continue;
    48	            }
    49	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    50	        }
    51	
    52	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    53	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
    54	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
    55	
    56	        long reservationId = reservationRepository.getNextId();
    57	        Reservation reservation = new Reservation(reservationId, roomNumber, guestName, guestEmail, guestCpf,
    58	                                                 checkIn, checkOut, guests, ratePlan, subtotal, discount, total);
    59	        reservationRepository.save(reservation);
    60	        return reservation;
    61	    }
    62	
    63	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) {
    64	        Reservation reservation = reservationRepository.findById(reservationId);
    65	        if (reservation == null) {
    66	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    67	        }
    68	
    69	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    70	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    71	        }
    72	
    73	        reservation.setStatus(ReservationStatus.CONFIRMED);
    74	        reservation.setAmountPaid(amountPaid);
    75	
    76	        String recipientEmail = reservation.getGuestEmail();
    77	        String subject = "Reserva confirmada - Pousada Maré Alta";
    78	        String body = receiptService.generateConfirmationEmail(reservation);
    79	
    80	        Message guestMessage = new Message(
    81	            messageRepository.getNextMessageId(),
    82	            Message.MessageChannel.EMAIL,
    83	            recipientEmail,
    84	            subject,
    85	            body
    86	        );
    87	        messageRepository.save(guestMessage);
    88	
    89	        ReservationStatus previousStatus = ReservationStatus.PENDING;
    90	        eventPublisher.publish(new ReservationEvent(ReservationEvent.Type.CONFIRMED, reservation, previousStatus));
    91	
    92	        return reservation;
    93	    }
    94	
    95	    public Reservation checkIn(long reservationId) {
    96	        Reservation reservation = reservationRepository.findById(reservationId);
    97	        if (reservation == null) {
    98	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    99	        }
   100	
   101	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   102	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   103	        }
   104	
   105	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   106	        return reservation;
   107	    }
   108	
   109	    public Reservation checkOut(long reservationId) {
   110	        Reservation reservation = reservationRepository.findById(reservationId);
   111	        if (reservation == null) {
   112	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   113	        }
   114	
   115	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   116	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   117	        }
   118	
   119	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   120	        return reservation;
   121	    }
   122	
   123	    public Reservation cancelReservation(long reservationId) {
   124	        Reservation reservation = reservationRepository.findById(reservationId);
   125	        if (reservation == null) {
   126	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   127	        }
   128	
   129	        ReservationStatus previousStatus = reservation.getStatus();
   130	        if (previousStatus != ReservationStatus.PENDING && previousStatus != ReservationStatus.CONFIRMED &&
   131	            previousStatus != ReservationStatus.CHECKED_IN) {
   132	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   133	        }
   134	
   135	        ReservationStatus beforeCancellation = reservation.getStatus();
   136	        reservation.setStatus(ReservationStatus.CANCELLED);
   137	
   138	        if (previousStatus == ReservationStatus.CONFIRMED || previousStatus == ReservationStatus.CHECKED_IN) {
   139	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
   140	                reservation.setRefund(reservation.getAmountPaid());
   141	            } else {
   142	                reservation.setRefund(BigDecimal.ZERO);
   143	            }
   144	        } else {
   145	            reservation.setRefund(BigDecimal.ZERO);
   146	        }
   147	
   148	        if (beforeCancellation != ReservationStatus.PENDING) {
   149	            eventPublisher.publish(new ReservationEvent(ReservationEvent.Type.CANCELLED, reservation, beforeCancellation));
   150	        }
   151	
   152	        return reservation;
   153	    }
   154	
   155	    public String getReceipt(long reservationId) {
   156	        Reservation reservation = reservationRepository.findById(reservationId);
   157	        if (reservation == null) {
   158	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   159	        }
   160	
   161	        if (!reservation.isPaid()) {
   162	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   163	        }
   164	
   165	        return receiptService.generateReceipt(reservation);
   166	    }
   167	}
