   199	    private static void handleError(io.javalin.http.Context ctx, String error) {
   200	        String message = switch (error) {
   201	            case "ROOM_NOT_FOUND" -> "Quarto não encontrado";
   202	            case "RESERVATION_NOT_FOUND" -> "Reserva não encontrada";
   203	            case "ROOM_UNAVAILABLE" -> "Quarto não disponível para as datas solicitadas";
   204	            case "OPERATION_NOT_ALLOWED" -> "Operação não permitida para este status de reserva";
   205	            case "CAPACITY_EXCEEDED" -> "Número de hóspedes excede a capacidade do quarto";
   206	            default -> "Requisição inválida";
   207	        };
   208	
   209	        int statusCode = switch (error) {
   210	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
   211	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
   212	            case "CAPACITY_EXCEEDED" -> 422;
