   206	            default -> "Requisição inválida";
   207	        };
   208	
   209	        int statusCode = switch (error) {
   210	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
   211	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
   212	            case "CAPACITY_EXCEEDED" -> 422;
   213	            default -> 400;
   214	        };
   215	
   216	        ctx.status(statusCode).json(new ErrorDto(error, message));
   217	    }
   218	}

