     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        Month month = date.getMonth();
    14	        if (month == Month.JULY) {
    15	            return true;
    16	        }
    17	        if (month == Month.DECEMBER || month == Month.JANUARY || month == Month.FEBRUARY) {
    18	            int day = date.getDayOfMonth();
    19	            if (month == Month.DECEMBER) {
    20	                return day >= 15;
    21	            }
    22	            return true;
    23	        }
    24	        return false;
    25	    }
    26	
    27	    public static BigDecimal calculateNightlyPrice(double baseRate, LocalDate date) {
    28	        BigDecimal price = new BigDecimal(baseRate);
    29	        if (isHighSeason(date)) {
    30	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
    31	        }
    32	        return round(price);
    33	    }
    34	
    35	    public static BigDecimal calculateSubtotal(double baseRate, LocalDate checkIn, LocalDate checkOut) {
    36	        BigDecimal subtotal = BigDecimal.ZERO;
    37	        LocalDate current = checkIn;
    38	        while (current.isBefore(checkOut)) {
    39	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
    40	            current = current.plusDays(1);
    41	        }
    42	        return round(subtotal);
    43	    }
    44	
    45	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    46	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    47	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    48	        }
    49	        return BigDecimal.ZERO;
    50	    }
    51	
    52	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    53	        return round(subtotal.subtract(discount));
    54	    }
    55	
    56	    public static BigDecimal round(BigDecimal value) {
    57	        return value.setScale(2, RoundingMode.HALF_EVEN);
    58	    }
    59	}
