    94	                   .append(reservation.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",")
    95	                   .append(reservation.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)).append("\n");
