   108	        for (Reservation reservation : reservationRepository.findByMonthStarting(yearMonth.getYear(), yearMonth.getMonthValue())) {
   109	            java.math.BigDecimal amount = reservation.getAmountPaid().subtract(reservation.getRefund() == null ? java.math.BigDecimal.ZERO : reservation.getRefund());
   110	            totalAmount = totalAmount.add(amount);
