   115	               .append(reservation.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",")
   116	               .append(reservation.getStatus()).append(",")
   117	               .append(String.format("%.2f", amount)).append("\n");
   118	        }
   119	
   120	        csv.append("total,,,,").append(String.format("%.2f", totalAmount)).append("\n");
